// Aggregate the raw feed into per-(role_id, from_stage, to_stage) counts for today.
// Output one item per (role, stage) pair with: entered, advanced, rejected, dwell_seconds_p50.
const events = $input.all().flatMap(i => i.json.results || []);

const byKey = new Map();
for (const e of events) {
  if (!e.roleId || !e.fromStage || !e.toStage) continue;
  const key = `${e.roleId}::${e.fromStage}::${e.toStage}`;
  if (!byKey.has(key)) {
    byKey.set(key, {
      role_id: e.roleId,
      role_name: e.roleName || e.roleId,
      from_stage: e.fromStage,
      to_stage: e.toStage,
      entered: 0,
      advanced: 0,
      rejected: 0,
      dwell_seconds: [],
    });
  }
  const row = byKey.get(key);
  row.entered += 1;
  if (e.outcome === 'advanced') row.advanced += 1;
  if (e.outcome === 'rejected') row.rejected += 1;
  if (typeof e.dwellSeconds === 'number') row.dwell_seconds.push(e.dwellSeconds);
}

const pct = (a, b) => (b > 0 ? a / b : null);
const p50 = (arr) => {
  if (arr.length === 0) return null;
  const sorted = [...arr].sort((x, y) => x - y);
  return sorted[Math.floor(sorted.length / 2)];
};

const out = [];
for (const row of byKey.values()) {
  out.push({
    json: {
      role_id: row.role_id,
      role_name: row.role_name,
      from_stage: row.from_stage,
      to_stage: row.to_stage,
      entered: row.entered,
      advanced: row.advanced,
      rejected: row.rejected,
      conversion_rate_today: pct(row.advanced, row.entered),
      dwell_seconds_p50: p50(row.dwell_seconds),
      window_start: $now.minus({hours: 24}).toISO(),
      window_end: $now.toISO(),
    },
  });
}

return out;

// Decide which anomaly type (if any) to flag for this (role, stage) row.
// Inputs: today's aggregate (from upstream item) joined with the baseline row.
const today = $('Aggregate Per-Stage Conversion (24h)').item.json;
const baseline = $json;

const MIN_SAMPLE = 20;       // do not flag rare stages with too little data
const Z_THRESHOLD = 2.0;     // 2 stddev below baseline
const NEW_ROLE_DAYS = 7;     // for new-role-no-movement
const DWELL_MULTIPLIER = 1.5; // p50 dwell vs SLA before flagging stalled

const flags = [];

if (
  baseline.conversion_rate_mean != null &&
  baseline.sample_size >= MIN_SAMPLE &&
  today.conversion_rate_today != null &&
  baseline.conversion_rate_stddev > 0
) {
  const z = (today.conversion_rate_today - baseline.conversion_rate_mean) / baseline.conversion_rate_stddev;
  if (z <= -Z_THRESHOLD) {
    flags.push({
      anomaly_type: 'stage_conversion_drop',
      severity: z <= -3 ? 'high' : 'medium',
      z_score: z,
      current_value: today.conversion_rate_today,
      baseline_value: baseline.conversion_rate_mean,
      route_to: 'recruiter',
    });
  }
}

if (
  baseline.stage_sla_seconds &&
  today.dwell_seconds_p50 &&
  today.dwell_seconds_p50 > baseline.stage_sla_seconds * DWELL_MULTIPLIER
) {
  flags.push({
    anomaly_type: 'candidate_stalled',
    severity: 'medium',
    current_value: today.dwell_seconds_p50,
    baseline_value: baseline.stage_sla_seconds,
    route_to: 'recruiter+hiring_manager',
  });
}

if (today.entered === 0 && baseline.sample_size < MIN_SAMPLE) {
  flags.push({
    anomaly_type: 'new_role_no_movement',
    severity: 'low',
    current_value: 0,
    baseline_value: null,
    route_to: 'recruiting_leader+hiring_manager',
    note: `Less than ${MIN_SAMPLE} historical applications and zero today; thresholds suppressed.`,
  });
}

// Emit one item per flag so downstream nodes can fan out.
return flags.map(f => ({
  json: {
    role_id: today.role_id,
    role_name: today.role_name,
    from_stage: today.from_stage,
    to_stage: today.to_stage,
    window_start: today.window_start,
    window_end: today.window_end,
    sample_size: baseline.sample_size,
    ...f,
  },
}));

