// Pick the Slack channel based on anomaly_type.
const alert = $('Detect Anomalies').item.json;
const narrative = ($json.content && $json.content[0] && $json.content[0].text) || 'No narrative generated.';

const routing = {
  stage_conversion_drop: '#recruiting-alerts',
  candidate_stalled: '#recruiting-alerts',
  time_to_hire_trend: '#recruiting-leadership',
  source_channel_drop: '#sourcing',
  new_role_no_movement: '#recruiting-leadership',
};

const channel = routing[alert.anomaly_type] || '#recruiting-alerts';

const pct = (n) => (n == null ? 'n/a' : `${(n * 100).toFixed(1)}%`);
const current =
  alert.anomaly_type === 'stage_conversion_drop' ? pct(alert.current_value)
  : alert.anomaly_type === 'candidate_stalled' ? `${Math.round(alert.current_value / 86400)}d dwell p50`
  : String(alert.current_value);
const baseline =
  alert.anomaly_type === 'stage_conversion_drop' ? pct(alert.baseline_value)
  : alert.anomaly_type === 'candidate_stalled' ? `${Math.round((alert.baseline_value || 0) / 86400)}d SLA`
  : String(alert.baseline_value);

return [{
  json: {
    channel,
    text: `*${alert.anomaly_type.replace(/_/g, ' ')}* — ${alert.role_name} · ${alert.from_stage} → ${alert.to_stage}\nCurrent: ${current} | Baseline: ${baseline} | Severity: ${alert.severity}\n${narrative}\n<https://app.ashbyhq.com/jobs/${alert.role_id}|Open in Ashby>`,
  },
}];

// Reshape time-to-hire breaches into the same alert envelope used by the per-stage path.
return $input.all().map(({ json }) => ({
  json: {
    role_id: json.role_id,
    role_name: json.role_name,
    from_stage: 'overall',
    to_stage: 'hired',
    anomaly_type: 'time_to_hire_trend',
    severity: json.rolling_7d_tth > json.tth_threshold_days * 1.25 ? 'high' : 'medium',
    current_value: json.rolling_7d_tth,
    baseline_value: json.tth_baseline_days,
    sample_size: null,
    window_start: $now.minus({days: 7}).toISO(),
    window_end: $now.toISO(),
  },
}));
